#include <bits/stdc++.h>

using namespace std;

using ll = long long;

template<typename T>
istream& operator>>(istream& is, vector<T>& v) {
    for (auto& x : v) is >> x;
    return is;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<vector<ll>> a(n);
    for (int i = 0; i < n; ++i) {
        int t;
        cin >> t;
        a[i].resize(t);
        cin >> a[i];
        if (t > k) a[i].resize(k);
    }

    vector<vector<ll>> pref(n);
    for (int i = 0; i < n; ++i) {
        pref[i].resize(a[i].size());
        for (int j = 0; j < (int)a[i].size(); ++j) {
            pref[i][j] = a[i][j] + (j ? pref[i][j - 1] : 0LL);
        }
    }

    vector<vector<int>> pos(n, vector<int>(k, 0));

    for (int len = 1; len <= k; ++len) {
        vector<pair<ll, int>> v;
        for (int i = 0; i < n; ++i) {
            if ((int)pref[i].size() >= len) {
                v.emplace_back(pref[i][len - 1], i);
            }
        }

        sort(v.rbegin(), v.rend());

        for (int rank = 0; rank < (int)v.size(); ++rank) {
            pos[v[rank].second][len - 1] = rank;
        }
    }

    vector<vector<ll>> only_full(n + 1, vector<ll>(k + 1, 0));
    vector<vector<ll>> partial(n + 1, vector<ll>(k + 1, 0));

    for (int i = 0; i < n; ++i) {
        only_full[i + 1] = only_full[i];
        partial[i + 1] = partial[i];

        int size = (int)a[i].size();
        ll total = size ? pref[i].back() : 0;

        for (int j = k - size; j >= 0; --j) {
            only_full[i + 1][j + size] =
                max(only_full[i + 1][j + size], only_full[i][j] + total);
            partial[i + 1][j + size] =
                max(partial[i + 1][j + size], partial[i][j] + total);
        }

        for (int len = 1; len <= size; ++len) {
            int count_before = pos[i][len - 1] * len;
            if (count_before > k) continue;

            for (int j = 0; j + len <= k; ++j) {
                partial[i + 1][j + len] =
                    max(partial[i + 1][j + len],
                        only_full[i][j] + pref[i][len - 1]);
            }
        }
    }

    cout << max(only_full[n][k], partial[n][k]) << '\n';
    return 0;
}

